"use strict";

const crypto = require("crypto");

// Configuration-driven serialization library
// Supports multiple merge strategies based on environment
const MERGE_STRATEGIES = {
  shallow: "shallow",
  deep: "deep",
  recursive: "recursive"
};

class SerializationConfig {
  constructor(options = {}) {
    this.strategy = options.strategy || MERGE_STRATEGIES.deep;
    this.maxDepth = options.maxDepth || 32;
    this.allowCustomKeys = options.allowCustomKeys !== undefined ? options.allowCustomKeys : true;
    this.keyFilter = options.keyFilter || null;
    this.encoding = options.encoding || "utf8";
  }
}

function createDefaultConfig() {
  const env = process.env.SERIALIZER_MODE || "production";
  const config = new SerializationConfig({
    strategy: env === "development" ? MERGE_STRATEGIES.recursive : MERGE_STRATEGIES.deep,
    allowCustomKeys: env === "development",
    maxDepth: env === "development" ? 64 : 16
  });
  return config;
}

// Key validation - checks for obviously dangerous keys
function isReservedKey(key) {
  const reserved = ["constructor", "__defineGetter__", "__defineSetter__"];
  return reserved.includes(key);
}

// Determines if a property path segment is safe to traverse
function isTraversalSafe(segment, config) {
  if (!config.allowCustomKeys && segment.startsWith("_")) {
    return false;
  }
  if (isReservedKey(segment)) {
    return false;
  }
  return true;
}

// Core merge implementation with depth tracking
function mergeObjects(target, source, config, currentDepth = 0) {
  if (currentDepth > config.maxDepth) {
    throw new Error("Maximum merge depth exceeded");
  }

  if (typeof source !== "object" || source === null) {
    return source;
  }

  if (typeof target !== "object" || target === null) {
    target = {};
  }

  const keys = Object.keys(source);

  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];

    if (!isTraversalSafe(key, config)) {
      continue;
    }

    const sourceVal = source[key];
    const targetVal = target[key];

    if (config.strategy === MERGE_STRATEGIES.shallow) {
      target[key] = sourceVal;
    } else if (isPlainObject(sourceVal)) {
      target[key] = mergeObjects(
        isPlainObject(targetVal) ? targetVal : {},
        sourceVal,
        config,
        currentDepth + 1
      );
    } else {
      target[key] = sourceVal;
    }
  }

  return target;
}

// Check if value is a plain object
function isPlainObject(val) {
  if (typeof val !== "object" || val === null) return false;
  const proto = Object.getPrototypeOf(val);
  return proto === Object.prototype || proto === null;
}

// Deserialize from wire format with merge into existing state
function deserializePayload(buffer, existingState = {}) {
  const config = createDefaultConfig();
  let parsed;

  try {
    const str = Buffer.isBuffer(buffer) ? buffer.toString(config.encoding) : String(buffer);
    parsed = JSON.parse(str);
  } catch (e) {
    throw new Error("Invalid serialization format: " + e.message);
  }

  // Validate top-level structure
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new Error("Payload must be a non-null object");
  }

  // Apply key filter if configured
  if (config.keyFilter) {
    const filtered = {};
    for (const k of Object.keys(parsed)) {
      if (config.keyFilter(k)) {
        filtered[k] = parsed[k];
      }
    }
    parsed = filtered;
  }

  return mergeObjects(existingState, parsed, config);
}

// Serialize state to wire format
function serializeState(state) {
  const config = createDefaultConfig();
  const json = JSON.stringify(state);
  return Buffer.from(json, config.encoding);
}

// Compute integrity hash for serialized data
function computeIntegrity(buffer) {
  return crypto.createHash("sha256").update(buffer).digest("hex");
}

module.exports = {
  deserializePayload,
  serializeState,
  computeIntegrity,
  SerializationConfig,
  createDefaultConfig,
  MERGE_STRATEGIES
};
